  <button
    onClick={onClick}
    className={`w-12 h-12 flex items-center justify-center rounded-full transition-all duration-300 ${
      active ? 'bg-primary/10 text-primary hover:bg-primary/20' : 'bg-surface hover:bg-gray-100 text-text_secondary'
    }`}
    title={label}
  >
    {icon}
  </button>
);

